<?php
namespace App\Http\Controllers;
use App\Models\{Project,ProjectFile,ProjectFolder}; use Illuminate\Http\Request; use Illuminate\Support\Facades\{Auth,Storage};
class ProjectFileBrowserController extends Controller {
 private function access(Project $project):void{$this->authorize('projects-show',$project);}
 private function resolveFolder(Project $project, ?int $id):?ProjectFolder{return $id?ProjectFolder::where('project_id',$project->id)->findOrFail($id):null;}
 public function folder(Request $r,Project $project){$this->access($project);$parent=$this->resolveFolder($project,$r->integer('parent_id'));$r->validate(['name'=>'required|string|max:255']);ProjectFolder::create(['project_id'=>$project->id,'parent_id'=>$parent?->id,'name'=>$r->name,'created_by'=>Auth::id()]);return back()->with('success','Folder created.');}
 public function upload(Request $r,Project $project){$this->access($project);$r->validate(['file'=>'required|file|max:20480','folder_id'=>'nullable|integer']);$folder=$this->resolveFolder($project,$r->integer('folder_id'));$file=$r->file('file');$path=$file->store('project-files/'.$project->id);ProjectFile::create(['project_id'=>$project->id,'folder_id'=>$folder?->id,'name'=>$file->getClientOriginalName(),'path'=>$path,'mime_type'=>$file->getMimeType(),'size'=>$file->getSize(),'uploaded_by'=>Auth::id()]);return back()->with('success','File uploaded.');}
 public function download(Project $project,ProjectFile $file){$this->access($project);abort_unless($file->project_id===$project->id,404);return Storage::download($file->path,$file->name);}
 public function downloadFolder(Project $project,ProjectFolder $folder){$this->access($project);abort_unless($folder->project_id===$project->id,404);abort_unless(class_exists(\ZipArchive::class),500,'ZIP support is not available.');$zipPath=tempnam(sys_get_temp_dir(),'project-folder-');$zip=new \ZipArchive();$zip->open($zipPath,\ZipArchive::CREATE|\ZipArchive::OVERWRITE);$add=function(ProjectFolder $current,string $prefix) use (&$add,$zip,$project){$files=ProjectFile::where('project_id',$project->id)->where('folder_id',$current->id)->get();foreach($files as $file){if(Storage::exists($file->path))$zip->addFile(Storage::path($file->path),$prefix.$file->name);}$children=ProjectFolder::where('project_id',$project->id)->where('parent_id',$current->id)->get();foreach($children as $child){$add($child,$prefix.$child->name.'/');}};$add($folder,$folder->name.'/');$zip->close();return response()->download($zipPath,$folder->name.'.zip')->deleteFileAfterSend(true);}
 public function destroyFile(Project $project,ProjectFile $file){$this->access($project);abort_unless($file->project_id===$project->id,404);Storage::delete($file->path);$file->delete();return back()->with('success','File deleted.');}
 public function destroyFolder(Project $project,ProjectFolder $folder){$this->access($project);abort_unless($folder->project_id===$project->id,404);$folder->delete();return redirect()->route('projects.show',['project'=>$project,'tab'=>'files'])->with('success','Folder deleted.');}
}
